import{Vt as Vp,Yn as jp,f as Ar,x as DE}from"./chunk-CdnfGufr.js";import"./chunk-CIPJ1y8p.js";import{O as s,S as yt}from"./main.js";import"./chunk-B6_ZavlN.js";import{t as T}from"./chunk-BIWHBBD8.js";var c=class t{constructor(i){this.breadcrumbService=i;this.breadcrumbService.setBreadcrumbs([{label:`Home`,url:`/home`},{label:`Paradigms`,url:`/paradigms`},{label:`Motor Imagery`,url:`/paradigms/motor-imagery`}])}breadcrumbService;motor_imagery={section:`Motor Imagery`,link:`/paradigms/motor-imagery`,context:`Motor imagery (MI) refers to the <b>mental simulation of voluntary movement</b> in the absence of physical execution. It is a foundational paradigm in <b>brain-computer interface (BCI) systems</b>, enabling the decoding of <b>sensorimotor rhythms</b> linked to motor intent.`,definition:`Motor imagery is a <b>cognitive process</b> involving the internal rehearsal of <b>goal-directed movements</b> without generating muscular output. It activates <b>sensorimotor brain regions</b> and induces measurable changes in <b>EEG signals</b>, particularly within the <b>mu (8–12 Hz)</b> and <b>beta (13–30 Hz)</b> frequency bands.`,application:`Motor imagery is applied in <b>non-invasive BCI frameworks</b> across areas such as <b>neurorehabilitation</b>, <b>prosthetic control</b>, <b>augmentative communication</b>, and <b>cognitive training</b>. Its reliance on <b>endogenously generated brain activity</b> makes it suitable for both <b>clinical implementation</b> and <b>experimental research</b>.`,description:`Motor imagery (MI) enables the modulation of <b>sensorimotor cortical activity</b> through imagined movement, without muscular engagement. It is characterized by <b>event-related desynchronization (ERD)</b> and <b>event-related synchronization (ERS)</b> in the <b>sensorimotor cortex</b>, observable in EEG recordings. These neural patterns form the foundation for <b>intent decoding</b> in BCI applications, supporting interaction with external systems via <b>mental command</b>.`,explore:`Explore Motor Imagery Experiments`,explore_text:`The following experiments represent distinct implementations of the motor imagery paradigm, each varying in how <b>stimuli are presented and structured</b> across trials. These designs—such as <b>unilateral</b>, <b>bilateral</b>, <b>word-cued</b>, or <b>sequential</b>—are intended to evoke brain responses that can be classified reliably using non-invasive signals. Select an experiment to view its structure, methodology, and relevance in the context of BCI development.`,mechanism:`Motor imagery engages cortical and subcortical circuits typically involved in actual movement execution, including the <b>primary motor cortex (M1)</b>, <b>supplementary motor area (SMA)</b>, <b>premotor cortex</b>, and <b>parietal regions</b>. Although no overt movement occurs, MI elicits activity patterns that closely resemble those produced during real motion, particularly within the <b>sensorimotor cortex</b>. These activations influence <b>oscillatory brain dynamics</b>—notably <b>event-related desynchronization (ERD)</b> and <b>synchronization (ERS)</b>—which can be detected through non-invasive methods such as <b>EEG</b> or <b>fNIRS</b>.`,experiments:[{name:`Unilateral Motor Imagery`,link:`/paradigms/motor-imagery/unilateral`,description:`This experiment focuses on the <b>imagination of movement</b> in a <b>single limb</b>, typically the left or right hand. By isolating <b>unilateral activity</b>, researchers can analyze <b>contralateral desynchronization</b> in sensorimotor cortex and assess the feasibility of decoding <b>distinct motor intentions</b> from EEG signals.`},{name:`Bilateral Motor Imagery`,link:`/paradigms/motor-imagery/bilateral`,description:`This variant involves the <b>simultaneous</b> or <b>alternating imagination</b> of movements in <b>both hands</b>. It enables the study of <b>interhemispheric interactions</b> and <b>coordination patterns</b> in sensorimotor EEG activity.`},{name:`Intentional Motor Imagery`,link:`/paradigms/motor-imagery/intentional`,description:`This paradigm separates the <b>instruction phase</b> from the <b>execution cue</b>. Participants are first informed about the upcoming imagery task (e.g., “Left Hand”) and must <b>withhold execution</b> until a subsequent “Go” signal appears. This structure enables the study of <b>voluntary motor initiation</b>, <b>preparatory neural activity</b>, and <b>intentional control</b> in BCI contexts.`},{name:`Blocked Motor Imagery`,link:`/paradigms/motor-imagery/blocked`,description:`In this design, <b>motor imagery</b> and <b>resting trials</b> are grouped into <b>sequential blocks</b> instead of being randomized. This structure facilitates the analysis of <b>sustained cortical engagement</b> over time.`},{name:`Word-Cued Motor Imagery`,link:`/paradigms/motor-imagery/wordcued`,description:`Instead of arrows or icons, this experiment uses <b>textual stimuli</b> (e.g., “Left”, “Right”, “Feet”) to instruct motor imagery. It provides a <b>linguistic interface</b> for participants and enables analysis of <b>language-motor integration</b> effects.`},{name:`Sequential Motor Imagery`,link:`/paradigms/motor-imagery/sequential`,description:`Participants receive <b>temporally structured cues</b> guiding a <b>sequence of imagined actions</b> (e.g., grasp → rotate). This variant targets the decoding of <b>multi-phase motor plans</b> and explores <b>temporal segmentation</b> in EEG.`},{name:`Directional Transfer Motor Imagery`,link:`/paradigms/motor-imagery/directional`,description:`This experiment explores a <b>motor imagery paradigm</b> where <b>each class represents a transition</b> of motor intention between limbs (e.g., <b>Right Hand → Left Hand</b>). It investigates <b>interlimb coordination</b> and <b>asymmetric motor planning</b> through directional transitions.`}]};static ɵfac=function(e){return new(e||t)(Ar(s))};static ɵcmp=DE({type:t,selectors:[[`app-motor-imagery`]],decls:1,vars:1,consts:[[3,`paradigm`]],template:function(e,l){e&1&&Vp(0,`app-paradigm`,0),e&2&&jp(`paradigm`,l.motor_imagery)},dependencies:[yt,T],encapsulation:2})};export{c as MotorImagery};